@push('scripts')<script>(()=>{const list=document.getElementById('ads-list'),tpl=document.getElementById('ad-template');function renumber(){[...list.querySelectorAll('.ad-editor')].forEach((card,i)=>{card.querySelector('h2').textContent='Campagne '+(i+1);card.querySelectorAll('[data-name]').forEach(el=>{el.name=`ads[${i}][${el.dataset.name}]`})})}document.getElementById('add-ad').addEventListener('click',()=>{const empty=list.querySelector(':scope > p');if(empty)empty.remove();list.append(tpl.content.cloneNode(true));renumber()});list.addEventListener('click',e=>{if(e.target.closest('.remove-ad')){e.target.closest('.ad-editor').remove();renumber()}});renumber()})();</script>@endpush
